CREATE TABLE dbo.Price (
    ProductId INT PRIMARY KEY,
    ListPrice DECIMAL(10,2) NOT NULL,
    ValidFrom DATETIME2 GENERATED ALWAYS AS ROW START NOT NULL,
    ValidTo   DATETIME2 GENERATED ALWAYS AS ROW END   NOT NULL,
    PERIOD FOR SYSTEM_TIME (ValidFrom, ValidTo)
)
WITH (SYSTEM_VERSIONING = ON (HISTORY_TABLE = dbo.PriceHistory));

-- What did prices look like on New Year?
SELECT * FROM dbo.Price FOR SYSTEM_TIME AS OF '2026-01-01T00:00:00';

CREATE EXTERNAL DATA SOURCE Lake
WITH (LOCATION = 'abs://datalake@myaccount.blob.core.windows.net/sales');

CREATE EXTERNAL FILE FORMAT ParquetFF
WITH (FORMAT_TYPE = PARQUET);

CREATE EXTERNAL TABLE dbo.SalesExt (
    SaleId BIGINT, Amount DECIMAL(12,2), SoldAt DATE
)
WITH (LOCATION = '/2026/', DATA_SOURCE = Lake, FILE_FORMAT = ParquetFF);

CREATE TABLE dbo.AuditEvents (
    EventId BIGINT IDENTITY,
    EventType NVARCHAR(50) NOT NULL,
    OccurredAt DATETIME2 NOT NULL DEFAULT SYSUTCDATETIME()
)
WITH (LEDGER = ON (APPEND_ONLY = ON));

CREATE TABLE dbo.Person (Id INT PRIMARY KEY, Name NVARCHAR(100)) AS NODE;
CREATE TABLE dbo.Follows (Since DATE) AS EDGE;

INSERT INTO dbo.Follows ($from_id, $to_id, Since)
SELECT p1.$node_id, p2.$node_id, '2026-01-15'
FROM dbo.Person p1, dbo.Person p2
WHERE p1.Id = 1 AND p2.Id = 2;
